float eb_triangle_wrap(float phase)
{
    if (phase <= 1.0f) {
        if (phase < -1.0f)
            phase = fmodf(phase - 1.0f, 2.0f) + 1.0f;
    } else {
        phase = fmodf(phase + 1.0f, 2.0f) - 1.0f;
    }
    float v2 = phase + phase;       /* 2*p */
    if (phase >= -0.5f) {
        if (phase <= 0.5f)
            return v2;              /* 2*p */
        else
            return 2.0f - v2;       /* 2 - 2*p */
    } else {
        return -2.0f - v2;          /* -2 - 2*p */
    }
}

